1	//! I2C address-routing table and CLI device registry stub.
2	//!
3	//! `AddressMap` is what the bus state machine consults on every byte
4	//! completion to decide whether to ACK and which device receives the
5	//! event. It is wrapped in `Arc<Mutex<...>>` so the typed `I2cHandle`
6	//! can refresh routing on `set_address`.
7	//!
8	//! `build_i2c_device` is the string-keyed registry the CLI will parse
9	//! (`add1@0x50`, `tmp101@0x4A`, ...). For now the only known device is
10	//! `add1`; additional devices land in their own steps.
11	
12	use std::collections::HashMap;
13	use std::sync::{Arc, Mutex};
14	
15	use super::device::I2cDevice;
16	use super::devices::add1::Add1Device;
17	use super::devices::tmp101::Tmp101Device;
18	
19	/// Inner storage of the routing table. Public to the crate so the
20	/// typed handle can mutate it on `set_address`.
21	#[derive(Default)]
22	pub struct AddressMapInner {
23	    pub entries: HashMap<u8, Arc<Mutex<dyn I2cDevice>>>,
24	}
25	
26	/// Shared address-routing table. Cloning shares the same allocation so
27	/// the bus state and any number of `I2cHandle`s see the same routing.
28	#[derive(Clone, Default)]
29	pub struct AddressMap {
30	    inner: Arc<Mutex<AddressMapInner>>,
31	}
32	
33	impl AddressMap {
34	    pub fn new() -> Self {
35	        Self::default()
36	    }
37	
38	    pub(crate) fn shared(&self) -> Arc<Mutex<AddressMapInner>> {
39	        self.inner.clone()
40	    }
41	
42	    /// Look up the device at `addr`, returning a fresh `Arc` clone so
43	    /// the caller can drop the table lock before locking the device.
44	    pub fn lookup(&self, addr: u8) -> Option<Arc<Mutex<dyn I2cDevice>>> {
45	        self.inner.lock().ok()?.entries.get(&addr).cloned()
46	    }
47	
48	    /// Insert the device at `addr`. Returns `Err(AddressInUse)` if the
49	    /// slot is already taken.
50	    pub(crate) fn insert(
51	        &self,
52	        addr: u8,
53	        dev: Arc<Mutex<dyn I2cDevice>>,
54	    ) -> Result<(), super::handle::AddressInUse> {
55	        let mut g = self.inner.lock().expect("I2C address table poisoned");
56	        if g.entries.contains_key(&addr) {
57	            return Err(super::handle::AddressInUse { address: addr });
58	        }
59	        g.entries.insert(addr, dev);
60	        Ok(())
61	    }
62	
63	    pub fn clear(&self) {
64	        if let Ok(mut g) = self.inner.lock() {
65	            g.entries.clear();
66	        }
67	    }
68	
69	    pub fn is_empty(&self) -> bool {
70	        self.inner
71	            .lock()
72	            .map(|g| g.entries.is_empty())
73	            .unwrap_or(true)
74	    }
75	
76	    pub fn len(&self) -> usize {
77	        self.inner.lock().map(|g| g.entries.len()).unwrap_or(0)
78	    }
79	}
80	
81	/// Parse a CLI device spec and construct the device, returning the
82	/// shared `Arc<Mutex<dyn I2cDevice>>` form the bus's address-routing
83	/// table holds. Callers wanting a typed handle should use
84	/// `EmulatorCore::attach_i2c_device(D::new(...))` directly instead.
85	///
86	/// Spec syntax: `<name>@<addr>[?key=val&...]`. Address is 7-bit hex
87	/// (`0x50` or `50`). Recognised devices:
88	///   - `add1@<addr>[?wrap=<n>]`             — universal +1 test slave.
89	///   - `tmp101@<addr>[?temp=<f>][?config=<n>]` — TI temp sensor.
90	pub fn build_i2c_device(
91	    spec: &str,
92	) -> Result<std::sync::Arc<std::sync::Mutex<dyn I2cDevice>>, String> {
93	    use std::sync::{Arc, Mutex};
94	    let (name_addr, params) = match spec.split_once('?') {
95	        Some((head, tail)) => (head, Some(tail)),
96	        None => (spec, None),
97	    };
98	    let (name, addr_str) = name_addr
99	        .split_once('@')
100	        .ok_or_else(|| format!("device spec missing '@<addr>': {spec}"))?;
101	    let addr = parse_addr(addr_str)
102	        .ok_or_else(|| format!("invalid 7-bit address in spec '{spec}'"))?;
103	    match name {
104	        "add1" => {
105	            let mut wrap: u16 = 0x100;
106	            if let Some(p) = params {
107	                for kv in p.split('&') {
108	                    let (k, v) = kv
109	                        .split_once('=')
110	                        .ok_or_else(|| format!("bad param '{kv}' in '{spec}'"))?;
111	                    match k {
112	                        "wrap" => {
113	                            wrap = v.parse().map_err(|e| format!("bad wrap '{v}': {e}"))?
114	                        }
115	                        _ => return Err(format!("unknown add1 param '{k}' in '{spec}'")),
116	                    }
117	                }
118	            }
119	            Ok(Arc::new(Mutex::new(Add1Device::new(addr, wrap))))
120	        }
121	        "tmp101" => {
122	            let mut dev = Tmp101Device::new(addr);
123	            if let Some(p) = params {
124	                for kv in p.split('&') {
125	                    let (k, v) = kv
126	                        .split_once('=')
127	                        .ok_or_else(|| format!("bad param '{kv}' in '{spec}'"))?;
128	                    match k {
129	                        "temp" => {
130	                            let c: f32 =
131	                                v.parse().map_err(|e| format!("bad temp '{v}': {e}"))?;
132	                            dev.set_temperature(c);
133	                        }
134	                        "config" => {
135	                            let c: u8 = if let Some(rest) =
136	                                v.strip_prefix("0x").or_else(|| v.strip_prefix("0X"))
137	                            {
138	                                u8::from_str_radix(rest, 16)
139	                                    .map_err(|e| format!("bad config '{v}': {e}"))?
140	                            } else {
141	                                v.parse().map_err(|e| format!("bad config '{v}': {e}"))?
142	                            };
143	                            dev.set_config(c);
144	                        }
145	                        _ => return Err(format!("unknown tmp101 param '{k}' in '{spec}'")),
146	                    }
147	                }
148	            }
149	            Ok(Arc::new(Mutex::new(dev)))
150	        }
151	        other => Err(format!("unknown I2C device '{other}'")),
152	    }
153	}
154	
155	fn parse_addr(s: &str) -> Option<u8> {
156	    let s = s.trim();
157	    let n: u32 = if let Some(stripped) = s.strip_prefix("0x").or_else(|| s.strip_prefix("0X")) {
158	        u32::from_str_radix(stripped, 16).ok()?
159	    } else {
160	        s.parse().ok()?
161	    };
162	    if n > 0x7F { None } else { Some(n as u8) }
163	}
164	
165	#[cfg(test)]
166	mod tests {
167	    use super::*;
168	
169	    fn dev_address(spec: &str) -> u8 {
170	        let arc = build_i2c_device(spec).unwrap();
171	        let g = arc.lock().unwrap();
172	        g.address()
173	    }
174	
175	    fn dev_name(spec: &str) -> String {
176	        let arc = build_i2c_device(spec).unwrap();
177	        let g = arc.lock().unwrap();
178	        g.name().to_string()
179	    }
180	
181	    #[test]
182	    fn build_add1_default_wrap() {
183	        assert_eq!(dev_address("add1@0x50"), 0x50);
184	        assert_eq!(dev_name("add1@0x50"), "add1");
185	    }
186	
187	    #[test]
188	    fn build_add1_with_wrap() {
189	        assert_eq!(dev_address("add1@0x42?wrap=10"), 0x42);
190	    }
191	
192	    fn expect_err(spec: &str, needle: &str) {
193	        match build_i2c_device(spec) {
194	            Ok(_) => panic!("expected '{spec}' to fail"),
195	            Err(e) => assert!(e.contains(needle), "spec '{spec}' err: {e}"),
196	        }
197	    }
198	
199	    #[test]
200	    fn build_unknown_device_rejected() {
201	        expect_err("frobnicator@0x50", "frobnicator");
202	    }
203	
204	    #[test]
205	    fn build_invalid_address_rejected() {
206	        expect_err("add1@0xFF", "invalid");
207	    }
208	
209	    #[test]
210	    fn build_missing_at_rejected() {
211	        expect_err("add1", "missing '@");
212	    }
213	
214	    #[test]
215	    fn build_tmp101_default() {
216	        assert_eq!(dev_address("tmp101@0x4A"), 0x4A);
217	        assert_eq!(dev_name("tmp101@0x4A"), "tmp101");
218	    }
219	
220	    #[test]
221	    fn build_tmp101_with_temperature() {
222	        let _ = build_i2c_device("tmp101@0x4A?temp=23.5").unwrap();
223	    }
224	
225	    #[test]
226	    fn build_tmp101_with_config() {
227	        let _ = build_i2c_device("tmp101@0x4A?config=0x60").unwrap();
228	        let _ = build_i2c_device("tmp101@0x4A?config=32").unwrap();
229	    }
230	
231	    #[test]
232	    fn build_tmp101_unknown_param_rejected() {
233	        expect_err("tmp101@0x4A?wrap=10", "unknown tmp101 param");
234	    }
235	}
