1	//! EmulatorCore: shared emulator controller for CLI and Web UI
2	//!
3	//! Provides run_batch(), pause/resume, breakpoints, and I/O accessors.
4	//! Both the CLI debugger and Yew/WASM UI call this directly (no IPC).
5	
6	use crate::cpu::executor::{ExecuteResult, Executor};
7	use crate::cpu::instruction::{DecodedInstruction, Opcode};
8	use crate::cpu::state::{CpuState, DecodeRom};
9	use crate::loader;
10	
11	/// Why a batch stopped
12	#[derive(Debug, Clone, PartialEq, Eq)]
13	pub enum StopReason {
14	    /// Ran the requested number of instructions
15	    CycleLimit,
16	    /// Hit a breakpoint at this address
17	    Breakpoint(u32),
18	    /// CPU halted (executed halt sentinel)
19	    Halted,
20	    /// Invalid instruction encountered
21	    InvalidInstruction(u8),
22	    /// Emulator is paused (pause was requested)
23	    Paused,
24	    /// Stack overflow: SP went below stack base
25	    StackOverflow(u32),
26	    /// Stack underflow: SP went above stack top (initial SP)
27	    StackUnderflow(u32),
28	}
29	
30	/// Result of a run_batch call
31	#[derive(Debug, Clone)]
32	pub struct BatchResult {
33	    /// Number of instructions executed in this batch
34	    pub instructions_run: u64,
35	    /// Why execution stopped
36	    pub reason: StopReason,
37	    /// Number of new UART output bytes since batch started
38	    pub uart_bytes_added: usize,
39	    /// Whether LED state changed during batch
40	    pub led_changed: bool,
41	}
42	
43	/// Snapshot of CPU state for UI display
44	#[derive(Debug, Clone)]
45	pub struct CpuSnapshot {
46	    pub regs: [u32; 8],
47	    pub pc: u32,
48	    pub c: bool,
49	    pub halted: bool,
50	    pub intis: bool,
51	    pub cycles: u64,
52	    pub instructions: u64,
53	    pub led: u8,
54	    pub button: u8,
55	    pub uart_output_len: usize,
56	}
57	
58	/// The shared emulator core
59	#[derive(Clone)]
60	pub struct EmulatorCore {
61	    cpu: CpuState,
62	    executor: Executor,
63	    decode_rom: DecodeRom,
64	    breakpoints: Vec<u32>,
65	    paused: bool,
66	    /// Highest address written during load (tracks end of code+data)
67	    program_end: u32,
68	    /// Valid stack region bounds. Both non-zero enables checking.
69	    /// SP below stack_base → StackOverflow, SP above stack_top → StackUnderflow.
70	    /// Set both to 0 to disable (e.g., custom runtimes with non-EBR stacks).
71	    stack_base: u32,
72	    stack_top: u32,
73	}
74	
75	impl Default for EmulatorCore {
76	    fn default() -> Self {
77	        Self::new()
78	    }
79	}
80	
81	impl EmulatorCore {
82	    pub fn new() -> Self {
83	        Self {
84	            cpu: CpuState::new(),
85	            executor: Executor::new(),
86	            decode_rom: DecodeRom::new(),
87	            breakpoints: Vec::new(),
88	            paused: true, // start paused
89	            program_end: 0,
90	            stack_base: crate::cpu::state::EBR_BASE,
91	            stack_top: crate::cpu::state::INITIAL_SP,
92	        }
93	    }
94	
95	    // ===== Load =====
96	
97	    /// Load an LGO file into memory, set entry point
98	    pub fn load_lgo(&mut self, content: &str, entry: Option<u32>) -> Result<usize, String> {
99	        self.cpu = CpuState::new();
100	        let result = loader::load_lgo(content, &mut self.cpu)?;
101	        let start = entry.or(result.start_addr).unwrap_or(0);
102	        self.cpu.pc = start;
103	        self.paused = true;
104	        self.program_end = result.highest_address;
105	        Ok(result.bytes_loaded)
106	    }
107	
108	    /// Load assembled bytes into memory at given address
109	    pub fn load_program(&mut self, addr: u32, bytes: &[u8]) {
110	        self.cpu.load_program(addr, bytes);
111	        let end = addr + bytes.len() as u32;
112	        if end > self.program_end {
113	            self.program_end = end;
114	        }
115	    }
116	
117	    /// Set the program extent (highest address used by program code)
118	    pub fn load_program_extent(&mut self, end: u32) {
119	        if end > self.program_end {
120	            self.program_end = end;
121	        }
122	    }
123	
124	    /// Reset CPU (preserves memory)
125	    pub fn reset(&mut self) {
126	        self.cpu.reset();
127	        self.paused = true;
128	    }
129	
130	    /// Hard reset (clears memory too)
131	    pub fn hard_reset(&mut self) {
132	        self.cpu.hard_reset();
133	        self.paused = true;
134	    }
135	
136	    // ===== Run control =====
137	
138	    /// Run a batch of instructions. Returns what happened.
139	    pub fn run_batch(&mut self, max_instructions: u64) -> BatchResult {
140	        let uart_before = self.cpu.io.uart_output.len();
141	        let led_before = self.cpu.io.leds;
142	        let mut count = 0u64;
143	
144	        if self.cpu.halted {
145	            return BatchResult {
146	                instructions_run: 0,
147	                reason: StopReason::Halted,
148	                uart_bytes_added: 0,
149	                led_changed: false,
150	            };
151	        }
152	
153	        if self.paused {
154	            return BatchResult {
155	                instructions_run: 0,
156	                reason: StopReason::Paused,
157	                uart_bytes_added: 0,
158	                led_changed: false,
159	            };
160	        }
161	
162	        let reason = loop {
163	            if count >= max_instructions {
164	                break StopReason::CycleLimit;
165	            }
166	
167	            // Check breakpoints (skip on first instruction to allow continuing past one)
168	            if count > 0 && self.breakpoints.contains(&self.cpu.pc) {
169	                self.paused = true;
170	                break StopReason::Breakpoint(self.cpu.pc);
171	            }
172	
173	            match self.executor.step(&mut self.cpu) {
174	                ExecuteResult::Ok => {}
175	                ExecuteResult::Halted => {
176	                    break StopReason::Halted;
177	                }
178	                ExecuteResult::InvalidInstruction(byte) => {
179	                    self.cpu.halted = true;
180	                    break StopReason::InvalidInstruction(byte);
181	                }
182	                ExecuteResult::MemoryError(_) => {
183	                    self.cpu.halted = true;
184	                    break StopReason::Halted;
185	                }
186	            }
187	            count += 1;
188	
189	            // Check for stack bounds: overflow (below base) or underflow (above top)
190	            if self.stack_base != 0 {
191	                let sp = self.cpu.get_reg(4);
192	                if sp < self.stack_base {
193	                    self.cpu.halted = true;
194	                    break StopReason::StackOverflow(sp);
195	                } else if sp > self.stack_top {
196	                    self.cpu.halted = true;
197	                    break StopReason::StackUnderflow(sp);
198	                }
199	            }
200	        };
201	
202	        BatchResult {
203	            instructions_run: count,
204	            reason,
205	            uart_bytes_added: self.cpu.io.uart_output.len() - uart_before,
206	            led_changed: self.cpu.io.leds != led_before,
207	        }
208	    }
209	
210	    /// Execute exactly one instruction
211	    pub fn step(&mut self) -> BatchResult {
212	        self.paused = false;
213	        let result = self.run_batch(1);
214	        self.paused = true;
215	        result
216	    }
217	
218	    /// Step over: execute one instruction, but if it's a jal (call),
219	    /// run until return (matching stack depth)
220	    pub fn step_over(&mut self) -> BatchResult {
221	        let inst_byte = self.cpu.read_byte(self.cpu.pc);
222	        let decoded = self.decode_rom.decode(inst_byte);
223	        let is_call = if decoded != 0xFFF {
224	            let inst = DecodedInstruction::from_decoded(decoded);
225	            inst.opcode == Opcode::Jal
226	        } else {
227	            false
228	        };
229	
230	        if !is_call {
231	            return self.step();
232	        }
233	
234	        // It's a call — set a temporary breakpoint after the instruction
235	        let return_addr = self.cpu.pc + 1; // jal is 1 byte
236	        let had_bp = self.breakpoints.contains(&return_addr);
237	        if !had_bp {
238	            self.breakpoints.push(return_addr);
239	        }
240	        self.paused = false;
241	        let result = self.run_batch(10_000_000);
242	        if !had_bp {
243	            self.breakpoints.retain(|&a| a != return_addr);
244	        }
245	        self.paused = true;
246	        result
247	    }
248	
249	    /// Start running (unpause)
250	    pub fn resume(&mut self) {
251	        self.paused = false;
252	    }
253	
254	    /// Pause execution
255	    pub fn pause(&mut self) {
256	        self.paused = true;
257	    }
258	
259	    pub fn is_paused(&self) -> bool {
260	        self.paused
261	    }
262	
263	    pub fn is_halted(&self) -> bool {
264	        self.cpu.halted
265	    }
266	
267	    pub fn is_interrupt_in_service(&self) -> bool {
268	        self.cpu.intis
269	    }
270	
271	    pub fn is_running(&self) -> bool {
272	        !self.paused && !self.cpu.halted
273	    }
274	
275	    // ===== Breakpoints =====
276	
277	    pub fn add_breakpoint(&mut self, addr: u32) -> bool {
278	        if self.breakpoints.contains(&addr) {
279	            false
280	        } else {
281	            self.breakpoints.push(addr);
282	            true
283	        }
284	    }
285	
286	    pub fn remove_breakpoint(&mut self, addr: u32) -> bool {
287	        let len = self.breakpoints.len();
288	        self.breakpoints.retain(|&a| a != addr);
289	        self.breakpoints.len() < len
290	    }
291	
292	    pub fn remove_breakpoint_by_index(&mut self, index: usize) -> Option<u32> {
293	        if index < self.breakpoints.len() {
294	            Some(self.breakpoints.remove(index))
295	        } else {
296	            None
297	        }
298	    }
299	
300	    pub fn clear_breakpoints(&mut self) {
301	        self.breakpoints.clear();
302	    }
303	
304	    pub fn breakpoints(&self) -> &[u32] {
305	        &self.breakpoints
306	    }
307	
308	    pub fn has_breakpoint(&self, addr: u32) -> bool {
309	        self.breakpoints.contains(&addr)
310	    }
311	
312	    // ===== State queries =====
313	
314	    pub fn snapshot(&self) -> CpuSnapshot {
315	        CpuSnapshot {
316	            regs: [
317	                self.cpu.get_reg(0),
318	                self.cpu.get_reg(1),
319	                self.cpu.get_reg(2),
320	                self.cpu.get_reg(3),
321	                self.cpu.get_reg(4),
322	                self.cpu.get_reg(5),
323	                self.cpu.get_reg(6),
324	                self.cpu.get_reg(7),
325	            ],
326	            pc: self.cpu.pc,
327	            c: self.cpu.c,
328	            halted: self.cpu.halted,
329	            intis: self.cpu.intis,
330	            cycles: self.cpu.cycles,
331	            instructions: self.cpu.instructions,
332	            led: self.cpu.io.leds,
333	            button: self.cpu.io.switches,
334	            uart_output_len: self.cpu.io.uart_output.len(),
335	        }
336	    }
337	
338	    pub fn pc(&self) -> u32 {
339	        self.cpu.pc
340	    }
341	
342	    pub fn set_pc(&mut self, pc: u32) {
343	        self.cpu.pc = pc;
344	    }
345	
346	    pub fn get_reg(&self, reg: u8) -> u32 {
347	        self.cpu.get_reg(reg)
348	    }
349	
350	    pub fn set_reg(&mut self, reg: u8, value: u32) {
351	        self.cpu.set_reg(reg, value);
352	    }
353	
354	    /// Set valid stack bounds. SP below `base` → overflow, SP above `top` → underflow.
355	    /// Set both to 0 to disable stack checking (e.g., custom runtimes).
356	    pub fn set_stack_bounds(&mut self, base: u32, top: u32) {
357	        self.stack_base = base;
358	        self.stack_top = top;
359	    }
360	
361	    pub fn condition_flag(&self) -> bool {
362	        self.cpu.c
363	    }
364	
365	    pub fn cycles(&self) -> u64 {
366	        self.cpu.cycles
367	    }
368	
369	    /// Highest address written during load (end of code+data region)
370	    pub fn program_end(&self) -> u32 {
371	        self.program_end
372	    }
373	
374	    pub fn instructions_count(&self) -> u64 {
375	        self.cpu.instructions
376	    }
377	
378	    // ===== Memory access =====
379	
380	    pub fn read_byte(&self, addr: u32) -> u8 {
381	        self.cpu.read_byte(addr)
382	    }
383	
384	    pub fn write_byte(&mut self, addr: u32, value: u8) {
385	        self.cpu.write_byte(addr, value);
386	    }
387	
388	    pub fn read_word(&self, addr: u32) -> u32 {
389	        self.cpu.read_word(addr)
390	    }
391	
392	    pub fn read_memory(&self, addr: u32, len: u32) -> Vec<u8> {
393	        (0..len).map(|i| self.cpu.read_byte(addr + i)).collect()
394	    }
395	
396	    /// Direct read-only access to SRAM backing memory (0x000000-0x0FFFFF)
397	    pub fn sram(&self) -> &[u8] {
398	        &self.cpu.memory
399	    }
400	
401	    /// Direct read-only access to EBR backing memory (0xFEE000-0xFEFFFF)
402	    pub fn ebr(&self) -> &[u8] {
403	        &self.cpu.ebr
404	    }
405	
406	    // ===== I/O: LED and Button =====
407	
408	    /// Get raw LED register value (active-low: 0=ON, 1=OFF)
409	    pub fn get_led(&self) -> u8 {
410	        self.cpu.io.leds
411	    }
412	
413	    /// Check if LED D2 is visually on (active-low: register bit 0 == 0 means ON)
414	    pub fn is_led_on(&self) -> bool {
