465	    /// Attach an I2C device. The device's current 7-bit address is used
466	    /// to register it in the bus's routing table; the returned typed
467	    /// handle exposes mutation (`with`) and runtime address moves
468	    /// (`set_address`).
469	    pub fn attach_i2c_device<D: crate::peripherals::i2c::I2cDevice>(
470	        &mut self,
471	        dev: D,
472	    ) -> Result<
473	        crate::peripherals::i2c::I2cHandle<D>,
474	        crate::peripherals::i2c::AddressInUse,
475	    > {
476	        use std::sync::{Arc, Mutex};
477	        let typed: Arc<Mutex<D>> = Arc::new(Mutex::new(dev));
478	        let erased: Arc<Mutex<dyn crate::peripherals::i2c::I2cDevice>> = typed.clone();
479	        let addr = typed.lock().expect("attach: device lock poisoned").address();
480	        self.cpu.io.i2c.addresses.insert(addr, erased)?;
481	        let table = self.cpu.io.i2c.addresses.shared();
482	        Ok(crate::peripherals::i2c::I2cHandle::new(
483	            typed,
484	            std::sync::Arc::downgrade(&table),
485	        ))
486	    }
