549	    // ===== Disassembly =====
550	
551	    /// Disassemble one instruction at the given address.
552	    /// Returns (mnemonic_string, instruction_size_in_bytes).
553	    pub fn disassemble_at(&self, addr: u32) -> (String, u32) {
554	        use crate::cpu::instruction::{InstructionFormat, reg_name};
555	
556	        let inst_byte = self.cpu.read_byte(addr);
557	        let decoded = self.decode_rom.decode(inst_byte);
558	        if decoded == 0xFFF {
559	            return (format!(".byte 0x{:02X}", inst_byte), 1);
560	        }
561	
562	        let inst = DecodedInstruction::from_decoded(decoded);
563	        let format = inst.opcode.format();
564	        let size = match format {
565	            InstructionFormat::SingleByte => 1,
566	            InstructionFormat::TwoBytes => 2,
567	            InstructionFormat::FourBytes => 4,
568	        };
569	
570	        let text = match format {
571	            InstructionFormat::SingleByte => match inst.opcode {
572	                Opcode::Pop => format!("pop  {}", reg_name(inst.ra)),
573	                Opcode::Push => format!("push {}", reg_name(inst.ra)),
574	                Opcode::Jmp => format!("jmp  ({})", reg_name(inst.ra)),
575	                Opcode::Jal => {
576	                    format!("jal  {},({})", reg_name(inst.ra), reg_name(inst.rb))
577	                }
578	                Opcode::Mov if inst.rb == 5 => {
579	                    format!("mov  {},c", reg_name(inst.ra))
580	                }
581	                _ => {
582	                    format!(
583	                        "{:4} {},{}",
584	                        inst.opcode.mnemonic(),
585	                        reg_name(inst.ra),
586	                        reg_name(inst.rb)
587	                    )
588	                }
589	            },
590	            InstructionFormat::TwoBytes => {
591	                let imm = self.cpu.read_byte(addr + 1);
592	                let signed = imm as i8;
593	                match inst.opcode {
594	                    Opcode::Bra | Opcode::Brf | Opcode::Brt => {
595	                        let branch_base = addr.wrapping_add(4);
596	                        let target = CpuState::mask_24(
597	                            branch_base.wrapping_add(CpuState::sign_extend_8(imm)),
598	                        );
599	                        format!("{:4} 0x{:06X}", inst.opcode.mnemonic(), target)
600	                    }
601	                    Opcode::Lc | Opcode::Lcu | Opcode::AddImm => {
602	                        format!(
603	                            "{:4} {},{}",
604	                            inst.opcode.mnemonic(),
605	                            reg_name(inst.ra),
606	                            signed
607	                        )
608	                    }
609	                    _ => {
610	                        // Lb, Lbu, Lw, Sb, Sw with offset
611	                        if signed == 0 {
612	                            format!(
613	                                "{:4} {},({})",
614	                                inst.opcode.mnemonic(),
615	                                reg_name(inst.ra),
616	                                reg_name(inst.rb)
617	                            )
618	                        } else {
619	                            format!(
620	                                "{:4} {},{}({})",
621	                                inst.opcode.mnemonic(),
622	                                reg_name(inst.ra),
623	                                signed,
624	                                reg_name(inst.rb)
625	                            )
626	                        }
627	                    }
628	                }
629	            }
630	            InstructionFormat::FourBytes => {
631	                let b0 = self.cpu.read_byte(addr + 1) as u32;
632	                let b1 = self.cpu.read_byte(addr + 2) as u32;
633	                let b2 = self.cpu.read_byte(addr + 3) as u32;
634	                let imm24 = b0 | (b1 << 8) | (b2 << 16);
635	                format!(
636	                    "{:4} {},0x{:06X}",
637	                    inst.opcode.mnemonic(),
638	                    reg_name(inst.ra),
639	                    imm24
640	                )
641	            }
642	        };
643	
644	        (text, size)
645	    }
646	
647	    /// Disassemble N instructions starting at addr
648	    pub fn disassemble(&self, addr: u32, count: usize) -> Vec<(u32, String, u32)> {
649	        let mut result = Vec::with_capacity(count);
650	        let mut pc = addr;
651	        for _ in 0..count {
652	            let (text, size) = self.disassemble_at(pc);
653	            result.push((pc, text, size));
654	            pc = CpuState::mask_24(pc + size);
655	        }
656	        result
657	    }
658	}
