664	    /// Assemble `source` via the standalone `cor24-asm` binary and
665	    /// return the `.lgo` text. Used by tests below that previously
666	    /// called the in-tree `Assembler` directly. Requires `cor24-asm`
667	    /// on PATH (saga decision: the in-tree assembler is going away;
668	    /// production toolchain is the canonical assembler).
669	    fn asm_to_lgo(source: &str) -> String {
670	        use std::io::Write;
671	        use std::process::{Command, Stdio};
672	        let mut child = Command::new("cor24-asm")
673	            .arg("-")
674	            .stdin(Stdio::piped())
675	            .stdout(Stdio::piped())
676	            .stderr(Stdio::piped())
677	            .spawn()
678	            .expect("cor24-asm not on PATH; required by emulator tests");
679	        child
680	            .stdin
681	            .as_mut()
682	            .unwrap()
683	            .write_all(source.as_bytes())
684	            .unwrap();
685	        let output = child
686	            .wait_with_output()
687	            .expect("cor24-asm wait_with_output failed");
688	        if !output.status.success() {
689	            panic!(
690	                "cor24-asm failed: status={:?}\nstderr=\n{}",
691	                output.status.code(),
692	                String::from_utf8_lossy(&output.stderr),
693	            );
694	        }
695	        String::from_utf8(output.stdout).expect("cor24-asm output not UTF-8")
696	    }
