842	        emu.set_pc(0);
843	
844	        fn run_tick(emu: &mut EmulatorCore, steps: u32) {
845	            for _ in 0..steps {
846	                if emu.is_halted() {
847	                    break;
848	                }
849	                let r = emu.step();
850	                if matches!(
851	                    r.reason,
852	                    StopReason::Halted | StopReason::InvalidInstruction(_)
853	                ) {
854	                    break;
855	                }
856	            }
857	        }
858	
859	        // Init — prompt should appear
860	        run_tick(&mut emu, 500);
861	        assert_eq!(emu.get_uart_output(), "?", "Prompt should appear");
862	        assert!(!emu.is_halted(), "Should not be halted");
863	
864	        // Send 'a' (lowercase) → echoes 'A' (uppercase)
865	        emu.send_uart_byte(b'a');
866	        run_tick(&mut emu, 500);
867	        assert_eq!(emu.get_uart_output(), "?A", "'a' -> 'A'");
868	
869	        // Send 'B' (uppercase) → echoes 'B' as-is
870	        emu.send_uart_byte(b'B');
871	        run_tick(&mut emu, 500);
872	        assert_eq!(emu.get_uart_output(), "?AB", "'B' -> 'B'");
873	
874	        // Send '1' (digit) → echoes '1' as-is
875	        emu.send_uart_byte(b'1');
876	        run_tick(&mut emu, 500);
877	        assert_eq!(emu.get_uart_output(), "?AB1", "'1' -> '1'");
878	
879	        // Send '!' → halts
880	        emu.send_uart_byte(b'!');
881	        run_tick(&mut emu, 500);
882	        assert!(emu.is_halted(), "Should halt on '!'");
883	    }
