1	//! I2C bus state machine.
2	//!
3	//! Edge detection over (SCL, SDA) line transitions — START, STOP, byte
4	//! shift on SCL rising edge, ACK clock — combined with device dispatch
5	//! through the per-bus address-routing table. The slave-side SDA
6	//! pull-down (`slave_sda_pull`) is wired into the read of `IO_I2C_SDA`
7	//! so the master sees ACKs and slave-driven read bytes through the
8	//! same wired-AND a real I2C bus presents.
9	//!
10	//! Phase changes happen on SCL rises (sampling edge); slave-line pulls
11	//! are computed on SCL falls (between sampling edges) so they hold
12	//! across the upcoming SCL high period and are released by the next
13	//! fall — matching real I2C timing.
14	
15	use std::fmt;
16	
17	use serde::{Deserialize, Serialize};
18	
19	use crate::peripherals::i2c::device::Ack;
20	use crate::peripherals::i2c::log::{I2cEvent, I2cLog};
21	use crate::peripherals::i2c::registry::AddressMap;
22	
23	#[derive(Clone, Copy, Debug, Default, PartialEq, Eq, Serialize, Deserialize)]
24	pub enum I2cPhase {
25	    /// Bus quiet — both lines high.
26	    #[default]
27	    Idle,
28	    /// Saw START; awaiting first SCL rising edge of the address byte.
29	    Started,
30	    /// Shifting in a byte from master. `bits` accumulates MSB-first;
31	    /// `n` is the count of bits collected (1..=7).
32	    RxByte { bits: u8, n: u8 },
33	    /// 8 bits collected; the 9th SCL pulse is the ACK clock the slave
34	    /// drives (or NAK with no slave).
35	    AckMasterToSlave,
36	    /// Slave is shifting a byte out to the master. `bits` accumulates
37	    /// what was sent (for `last_byte`); `n` is bits sent (1..=7).
38	    TxByte { bits: u8, n: u8 },
39	    /// 8 bits read; master ACKs to continue or NAKs to end the read.
40	    AckSlaveToMaster,
41	    /// Saw STOP; resolves to Idle on the next bus event.
42	    Stopped,
43	}
44	
45	#[derive(Clone, Copy, Debug, Default, PartialEq, Eq, Serialize, Deserialize)]
46	pub enum I2cDir {
47	    #[default]
48	    Write,
49	    Read,
50	}
51	
52	/// I2C bus state — phase, addressing context, edge-detection memory,
53	/// device-routing table, and slave-line drive state.
54	#[derive(Clone, Default, Serialize, Deserialize)]
55	pub struct I2cBusState {
56	    pub phase: I2cPhase,
57	    /// 7-bit slave address, set when the address byte completes.
58	    /// Cleared on START / STOP.
59	    pub current_target: Option<u8>,
60	    pub current_dir: I2cDir,
61	    /// Most recent fully-decoded byte (address byte or write data).
62	    /// Cleared on START.
63	    pub last_byte: Option<u8>,
64	    /// Sticky 7-bit address last observed on the bus — survives STOP so
65	    /// tests and observers can assert "the bus addressed device X at
66	    /// some point during this run."
67	    pub last_addressed: Option<u8>,
68	    /// Count of START conditions seen — useful for smoke-tests that
69	    /// want to confirm the state machine made progress.
70	    pub transactions: u32,
71	    /// Effective SCL/SDA seen at the last `step()` call. Used for
72	    /// edge detection.
73	    pub last_scl: bool,
74	    pub last_sda: bool,
75	    /// Whether the slave is actively pulling SDA low. Read by
76	    /// `state.rs::read_io` to compute the wired-AND'ed effective line.
77	    /// Skipped from serde — runtime/transport state.
78	    #[serde(skip)]
79	    pub slave_sda_pull: bool,
80	    /// Byte the slave has buffered to send during the next TxByte. The
81	    /// MSB is shifted out on each TxByte SCL rise.
82	    #[serde(skip)]
83	    tx_byte: u8,
84	    /// ACK decision for the in-progress AckMasterToSlave clock; computed
85	    /// on the byte-completing rise, applied on the next fall.
86	    #[serde(skip)]
87	    pending_ack: Ack,
88	    /// Per-bus address-routing table. Cloning the bus state shares the
89	    /// table (Arc), so attached devices survive snapshot/restore as
90	    /// far as in-memory state is concerned.
91	    #[serde(skip, default)]
92	    pub addresses: AddressMap,
93	    /// Chronological log of bus events — START / STOP / address byte /
94	    /// per-byte writes and reads. Skipped from serde (transport state).
95	    #[serde(skip)]
96	    pub log: I2cLog,
97	}
98	
99	impl fmt::Debug for I2cBusState {
100	    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
101	        f.debug_struct("I2cBusState")
102	            .field("phase", &self.phase)
103	            .field("current_target", &self.current_target)
104	            .field("current_dir", &self.current_dir)
105	            .field("last_byte", &self.last_byte)
106	            .field("last_addressed", &self.last_addressed)
107	            .field("transactions", &self.transactions)
108	            .field("last_scl", &self.last_scl)
109	            .field("last_sda", &self.last_sda)
110	            .field("slave_sda_pull", &self.slave_sda_pull)
111	            .field("attached", &self.addresses.len())
112	            .field("log_entries", &self.log.len())
113	            .finish()
114	    }
115	}
116	
117	impl I2cBusState {
118	    pub fn new() -> Self {
119	        Self {
120	            phase: I2cPhase::Idle,
121	            current_target: None,
122	            current_dir: I2cDir::Write,
123	            last_byte: None,
124	            last_addressed: None,
125	            transactions: 0,
126	            last_scl: true,
127	            last_sda: true,
128	            slave_sda_pull: false,
129	            tx_byte: 0,
130	            pending_ack: Ack::Nak,
131	            addresses: AddressMap::new(),
132	            log: I2cLog::new(),
133	        }
134	    }
135	
136	    /// Advance the state machine after the master writes either I2C
137	    /// line. `new_scl` / `new_sda` are the *effective* lines — the
138	    /// caller (state.rs::write_io) is expected to AND in the slave
139	    /// pull-down. `instruction` is the CPU's current instruction count,
140	    /// used to time-stamp log entries.
141	    pub fn step(&mut self, new_scl: bool, new_sda: bool, instruction: u64) {
142	        let prev_scl = self.last_scl;
143	        let prev_sda = self.last_sda;
144	
145	        // START/STOP edges (SCL high throughout) take precedence over
146	        // ordinary SCL rise/fall sampling.
147	        if new_scl && prev_scl && prev_sda && !new_sda {
148	            self.handle_start(instruction);
149	        } else if new_scl && prev_scl && !prev_sda && new_sda {
150	            self.handle_stop(instruction);
151	        } else if new_scl && !prev_scl {
152	            self.on_scl_rise(new_sda, instruction);
153	        } else if !new_scl && prev_scl {
154	            self.on_scl_fall();
155	        }
156	
157	        self.last_scl = new_scl;
158	        self.last_sda = new_sda;
159	    }
160	
161	    fn handle_start(&mut self, instruction: u64) {
162	        self.phase = I2cPhase::Started;
163	        self.current_target = None;
164	        self.last_byte = None;
165	        self.transactions = self.transactions.saturating_add(1);
166	        self.slave_sda_pull = false;
167	        self.log.push(I2cEvent::Start, instruction);
168	    }
169	
170	    fn handle_stop(&mut self, instruction: u64) {
171	        let target = self.current_target;
172	        self.phase = I2cPhase::Stopped;
173	        self.current_target = None;
174	        self.slave_sda_pull = false;
175	        if let Some(addr) = target
176	            && let Some(dev) = self.addresses.lookup(addr)
177	            && let Ok(mut d) = dev.lock()
178	        {
179	            d.on_stop();
180	        }
181	        self.log.push(I2cEvent::Stop, instruction);
182	    }
183	
184	    fn on_scl_rise(&mut self, sda: bool, instruction: u64) {
185	        let sda_bit = sda as u8;
186	        match self.phase {
187	            I2cPhase::Idle => {
188	                // Spurious clock with no START — ignore.
189	            }
190	            I2cPhase::Started => {
191	                self.phase = I2cPhase::RxByte {
192	                    bits: sda_bit,
193	                    n: 1,
194	                };
195	            }
196	            I2cPhase::RxByte { bits, n } => {
197	                let new_bits = (bits << 1) | sda_bit;
198	                let new_n = n + 1;
199	                if new_n == 8 {
200	                    self.last_byte = Some(new_bits);
201	                    let was_addr = self.current_target.is_none();
202	                    if was_addr {
203	                        let addr = new_bits >> 1;
204	                        self.current_target = Some(addr);
205	                        self.last_addressed = Some(addr);
206	                        self.current_dir = if new_bits & 1 == 1 {
207	                            I2cDir::Read
208	                        } else {
209	                            I2cDir::Write
210	                        };
211	                    }
212	                    self.phase = I2cPhase::AckMasterToSlave;
213	                    self.dispatch_byte_completion(was_addr, new_bits);
214	                    // Log AFTER dispatch so pending_ack reflects the
215	                    // device's response.
216	                    let acked = matches!(self.pending_ack, Ack::Ack);
217	                    if was_addr {
218	                        let addr = new_bits >> 1;
219	                        let dir = self.current_dir;
220	                        self.log.push(
221	                            I2cEvent::Address { addr, dir, ack: acked },
222	                            instruction,
223	                        );
224	                    } else {
225	                        let addr = self.current_target.unwrap_or(0);
226	                        self.log.push(
227	                            I2cEvent::WriteByte { addr, byte: new_bits, ack: acked },
228	                            instruction,
229	                        );
230	                    }
231	                } else {
232	                    self.phase = I2cPhase::RxByte {
233	                        bits: new_bits,
234	                        n: new_n,
235	                    };
236	                }
237	            }
238	            I2cPhase::AckMasterToSlave => {
239	                // 9th SCL rise — master is sampling the ACK on this
240	                // very edge. slave_sda_pull stays set through the whole
241	                // SCL-high period; it's released on the next SCL fall.
242	                self.phase = match self.current_dir {
243	                    I2cDir::Write => I2cPhase::RxByte { bits: 0, n: 0 },
244	                    I2cDir::Read => I2cPhase::TxByte { bits: 0, n: 0 },
245	                };
246	            }
247	            I2cPhase::TxByte { bits, n } => {
248	                // Master sampled bit on this rise — the bit was driven
249	                // on the previous fall via slave_sda_pull. Track what
250	                // was sent and advance.
251	                let bit_sent = (self.tx_byte >> 7) & 1;
252	                let new_bits = (bits << 1) | bit_sent;
253	                let new_n = n + 1;
254	                self.tx_byte <<= 1;
255	                if new_n == 8 {
256	                    self.last_byte = Some(new_bits);
257	                    self.phase = I2cPhase::AckSlaveToMaster;
258	                    let addr = self.current_target.unwrap_or(0);
259	                    self.log.push(
260	                        I2cEvent::ReadByte { addr, byte: new_bits },
261	                        instruction,
262	                    );
263	                } else {
264	                    self.phase = I2cPhase::TxByte {
265	                        bits: new_bits,
266	                        n: new_n,
267	                    };
268	                }
269	            }
270	            I2cPhase::AckSlaveToMaster => {
271	                // Master drove ACK/NAK; sample sda. ACK = SDA low.
272	                let master_acked = !sda;
273	                let target = self.current_target.unwrap_or(0);
274	                if let Some(dev) = self.addresses.lookup(target)
275	                    && let Ok(mut d) = dev.lock()
276	                {
277	                    if master_acked {
278	                        d.on_master_ack();
279	                        self.tx_byte = d.on_read_byte();
280	                    } else {
281	                        d.on_master_nak();
282	                    }
283	                }
284	                // Continue with another byte slot — if the master
285	                // chose NAK, it will issue STOP/repeated START before
286	                // any further clocks shift this state.
287	                self.phase = I2cPhase::TxByte { bits: 0, n: 0 };
288	            }
289	            I2cPhase::Stopped => {
290	                self.phase = I2cPhase::Idle;
291	            }
292	        }
293	    }
294	
295	    /// Compute slave_sda_pull for the upcoming SCL high period.
296	    /// Called on every SCL fall. The slave drives during the ACK clock
297	    /// (AckMasterToSlave) and during each TxByte bit; everywhere else
298	    /// it releases.
299	    fn on_scl_fall(&mut self) {
300	        match self.phase {
301	            I2cPhase::AckMasterToSlave => {
302	                self.slave_sda_pull = matches!(self.pending_ack, Ack::Ack);
303	            }
304	            I2cPhase::TxByte { .. } => {
305	                // Drive the current MSB of tx_byte. (Bit shift happens
306	                // on the rise after the master samples.)
307	                self.slave_sda_pull = (self.tx_byte >> 7) & 1 == 0;
308	            }
309	            _ => {
310	                self.slave_sda_pull = false;
311	            }
312	        }
313	    }
314	
315	    /// Dispatch the byte that just completed in RxByte to whichever
316	    /// device is currently addressed. `was_addr` is true on the first
317	    /// byte of the transaction (the address byte itself); otherwise
318	    /// the byte is treated as a master-to-slave data write.
319	    fn dispatch_byte_completion(&mut self, was_addr: bool, byte: u8) {
320	        let target = match self.current_target {
321	            Some(a) => a,
322	            None => {
323	                self.pending_ack = Ack::Nak;
324	                return;
325	            }
326	        };
327	        let dev_opt = self.addresses.lookup(target);
328	        let Some(dev) = dev_opt else {
329	            self.pending_ack = Ack::Nak;
330	            return;
331	        };
332	        let Ok(mut d) = dev.lock() else {
333	            self.pending_ack = Ack::Nak;
334	            return;
335	        };
336	        if was_addr {
337	            d.on_start();
338	            self.pending_ack = Ack::Ack;
339	            if matches!(self.current_dir, I2cDir::Read) {
340	                self.tx_byte = d.on_read_byte();
341	            }
342	        } else {
343	            self.pending_ack = d.on_write_byte(byte);
344	        }
345	    }
346	}
