34	pub const IO_LEDSWDAT: u32 = 0xFF0000;
35	/// Interrupt enable register: bit 0 = UART RX interrupt enable
36	pub const IO_INTENABLE: u32 = 0xFF0010;
37	/// I2C SCL line register: write bit 0 to drive (0 = pull low, 1 = release),
38	/// read bit 0 for the effective line state (open-drain wired-AND).
39	pub const IO_I2C_SCL: u32 = 0xFF0020;
40	/// I2C SDA line register: same semantics as `IO_I2C_SCL`.
41	pub const IO_I2C_SDA: u32 = 0xFF0021;
42	/// SPI data register: write the byte to be shifted out on MOSI; read
43	/// the byte shifted in on MISO. Stub today (returns 0 / no-op) — the
44	/// shift-register state and slave dispatch land in later saga steps.
45	pub const IO_SPI_DATA: u32 = 0xFF0030;
46	/// SPI clock line: master writes bit 0 to drive SCLK. Stub today.
