66	/// Direction of a UART transaction
67	#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize)]
68	pub enum UartDirection {
69	    /// Input: byte sent to CPU via RX (host → CPU)
70	    Input,
71	    /// Output: byte transmitted by CPU via TX (CPU → host)
72	    Output,
73	}
