75	/// A single UART transaction record
76	#[derive(Clone, Debug, Serialize, Deserialize)]
77	pub struct UartLogEntry {
78	    pub direction: UartDirection,
79	    pub byte: u8,
80	    pub instruction: u64,
81	}
