83	/// Chronological log of all UART input and output
84	#[derive(Clone, Default, Serialize, Deserialize)]
85	pub struct UartLog {
86	    entries: Vec<UartLogEntry>,
87	}
88	
89	impl UartLog {
90	    pub fn new() -> Self {
91	        Self {
92	            entries: Vec::new(),
93	        }
94	    }
95	
96	    pub fn push(&mut self, direction: UartDirection, byte: u8, instruction: u64) {
97	        self.entries.push(UartLogEntry {
98	            direction,
99	            byte,
100	            instruction,
101	        });
102	    }
103	
104	    pub fn clear(&mut self) {
105	        self.entries.clear();
106	    }
107	
108	    pub fn entries(&self) -> &[UartLogEntry] {
109	        &self.entries
110	    }
111	
112	    pub fn is_empty(&self) -> bool {
113	        self.entries.is_empty()
114	    }
115	
116	    /// Format the log with coalesced consecutive same-direction bytes.
117	    /// Echo patterns (alternating input/output of the same byte) are grouped
118	    /// so you see the input line followed by the output line.
119	    pub fn format(&self) -> String {
120	        if self.entries.is_empty() {
121	            return String::new();
122	        }
123	
124	        // Group consecutive same-direction entries
125	        let groups = self.coalesce();
126	
127	        let mut out = String::new();
128	        for (dir, bytes) in &groups {
129	            let label = match dir {
130	                UartDirection::Input => " IN",
131	                UartDirection::Output => "OUT",
132	            };
133	            out.push_str(&format!("  {}:  \"{}\"", label, escape_bytes(bytes)));
134	            out.push('\n');
135	        }
136	        out
137	    }
138	
139	    /// Coalesce entries into groups of (direction, bytes).
140	    /// Adjacent same-direction entries merge. Single-byte echo pairs
141	    /// (IN byte, OUT same-byte) are kept separate but not interleaved
142	    /// further — they naturally group when the program reads-then-writes
143	    /// in batches.
144	    fn coalesce(&self) -> Vec<(UartDirection, Vec<u8>)> {
145	        let mut groups: Vec<(UartDirection, Vec<u8>)> = Vec::new();
146	
147	        for entry in &self.entries {
148	            if let Some(last) = groups.last_mut()
149	                && last.0 == entry.direction
150	            {
151	                last.1.push(entry.byte);
152	                continue;
153	            }
154	            groups.push((entry.direction, vec![entry.byte]));
155	        }
156	
157	        groups
158	    }
159	}
