161	/// Escape bytes for display: show printable ASCII as-is, CR/LF as \r/\n, others as \xHH
162	fn escape_bytes(bytes: &[u8]) -> String {
163	    let mut s = String::new();
164	    for &b in bytes {
165	        match b {
166	            b'\n' => s.push_str("\\n"),
167	            b'\r' => s.push_str("\\r"),
168	            b'\t' => s.push_str("\\t"),
169	            0x20..=0x7E => s.push(b as char),
170	            _ => s.push_str(&format!("\\x{:02X}", b)),
171	        }
172	    }
173	    s
174	}
