247	            master_scl: true, // both I2C lines released high at reset
248	            master_sda: true,
249	            i2c: crate::cpu::i2c_bus::I2cBusState::new(),
250	            master_mosi: 0,    // idle: no byte staged
251	            master_sclk: false, // SPI mode 0 idle clock
252	            master_seln: true, // active-low: 1 = no slave selected
253	            spi: crate::cpu::spi_bus::SpiBusState::new(),
254	        }
255	    }
