258	/// A single instruction execution record
259	#[derive(Clone, Debug)]
260	pub struct TraceEntry {
261	    /// Program counter at start of instruction
262	    pub pc: u32,
263	    /// Decoded opcode
264	    pub opcode: Opcode,
265	    /// Destination register index
266	    pub ra: u8,
267	    /// Source register index
268	    pub rb: u8,
269	    /// Instruction size in bytes (1, 2, or 4)
270	    pub size: u8,
271	    /// 8-bit immediate (for 2-byte and 4-byte instructions)
272	    pub imm8: u8,
273	    /// 24-bit immediate (for 4-byte instructions)
274	    pub imm24: u32,
275	    /// Register state before execution
276	    pub regs_before: [u32; 8],
277	    /// Register state after execution
278	    pub regs_after: [u32; 8],
279	    /// Condition flag before
280	    pub c_before: bool,
281	    /// Condition flag after
282	    pub c_after: bool,
283	    /// SP before (convenience, same as regs_before\[4\])
284	    pub sp_before: u32,
285	    /// Instruction count at this point
