289	/// Register names for display
290	const REG_NAMES: [&str; 8] = ["r0", "r1", "r2", "fp", "sp", "z/c", "iv", "ir"];
291	
292	impl fmt::Display for TraceEntry {
293	    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
294	        // Disassemble the instruction
295	        let disasm = self.disassemble();
296	
297	        write!(
298	            f,
299	            "{:5} 0x{:06X}  {:<24}",
300	            self.instruction_num, self.pc, disasm
301	        )?;
302	
303	        // Show register changes
304	        let mut changes = Vec::new();
305	        for (i, name) in REG_NAMES.iter().enumerate() {
306	            if self.regs_before[i] != self.regs_after[i] {
307	                changes.push(format!(
308	                    "{}:0x{:06X}→0x{:06X}",
309	                    name, self.regs_before[i], self.regs_after[i]
310	                ));
311	            }
312	        }
313	        if self.c_before != self.c_after {
314	            changes.push(format!("c:{}→{}", self.c_before as u8, self.c_after as u8));
315	        }
316	        if !changes.is_empty() {
317	            write!(f, "  [{}]", changes.join(" "))?;
318	        }
319	
320	        Ok(())
321	    }
322	}
323	
324	impl TraceEntry {
325	    /// Disassemble this instruction into a human-readable string
326	    pub fn disassemble(&self) -> String {
327	        let ra = REG_NAMES[self.ra as usize];
328	        let rb = REG_NAMES[self.rb as usize];
329	        match self.opcode {
330	            Opcode::AddReg => format!("add     {},{}", ra, rb),
331	            Opcode::AddImm => format!("add     {},{}", ra, self.imm8 as i8),
332	            Opcode::And => format!("and     {},{}", ra, rb),
333	            Opcode::Bra => {
334	                let offset = self.imm8 as i8;
335	                let target = (self.pc as i64 + 4 + offset as i64) as u32 & 0xFFFFFF;
336	                format!("bra     0x{:06X}", target)
337	            }
338	            Opcode::Brf => {
339	                let offset = self.imm8 as i8;
340	                let target = (self.pc as i64 + 4 + offset as i64) as u32 & 0xFFFFFF;
341	                format!("brf     0x{:06X}", target)
342	            }
343	            Opcode::Brt => {
344	                let offset = self.imm8 as i8;
345	                let target = (self.pc as i64 + 4 + offset as i64) as u32 & 0xFFFFFF;
346	                format!("brt     0x{:06X}", target)
347	            }
348	            Opcode::Ceq => format!("ceq     {},{}", ra, rb),
349	            Opcode::Cls => format!("cls     {},{}", ra, rb),
350	            Opcode::Clu => format!("clu     {},{}", ra, rb),
351	            Opcode::Jal => format!("jal     {},({})", ra, rb),
352	            Opcode::Jmp => format!("jmp     ({})", ra),
353	            Opcode::La => format!("la      {},0x{:06X}", ra, self.imm24),
354	            Opcode::Lb => format!("lb      {},{}({})", ra, self.imm8 as i8, rb),
355	            Opcode::Lbu => format!("lbu     {},{}({})", ra, self.imm8, rb),
356	            Opcode::Lc => format!("lc      {},{}", ra, self.imm8 as i8),
357	            Opcode::Lcu => format!("lcu     {},{}", ra, self.imm8),
358	            Opcode::Lw => format!("lw      {},{}({})", ra, self.imm8 as i8, rb),
359	            Opcode::Mov => format!("mov     {},{}", ra, rb),
360	            Opcode::Mul => format!("mul     {},{}", ra, rb),
361	            Opcode::Or => format!("or      {},{}", ra, rb),
362	            Opcode::Pop => format!("pop     {}", ra),
363	            Opcode::Push => format!("push    {}", ra),
364	            Opcode::Sb => format!("sb      {},{}({})", ra, self.imm8 as i8, rb),
365	            Opcode::Shl => format!("shl     {},{}", ra, rb),
366	            Opcode::Sra => format!("sra     {},{}", ra, rb),
367	            Opcode::Srl => format!("srl     {},{}", ra, rb),
368	            Opcode::Sub => format!("sub     {},{}", ra, rb),
369	            Opcode::SubSp => format!("sub     sp,{}", self.imm24),
370	            Opcode::Sw => format!("sw      {},{}({})", ra, self.imm8 as i8, rb),
371	            Opcode::Sxt => format!("sxt     {},{}", ra, rb),
372	            Opcode::Xor => format!("xor     {},{}", ra, rb),
373	            Opcode::Zxt => format!("zxt     {},{}", ra, rb),
374	            Opcode::Invalid => format!("??? (0x{:02X})", self.imm8),
375	        }
376	    }
377	}
