379	/// Ring buffer of recent instruction trace entries
380	#[derive(Clone)]
381	pub struct TraceBuffer {
382	    entries: Vec<TraceEntry>,
383	    head: usize,
384	    capacity: usize,
385	    count: usize,
386	}
387	
388	impl Default for TraceBuffer {
389	    fn default() -> Self {
390	        Self::new(200)
391	    }
392	}
393	
394	impl TraceBuffer {
395	    /// Create a new trace buffer with given capacity
396	    pub fn new(capacity: usize) -> Self {
397	        Self {
398	            entries: Vec::with_capacity(capacity),
399	            head: 0,
400	            capacity,
401	            count: 0,
402	        }
403	    }
404	
405	    /// Record a trace entry
406	    pub fn push(&mut self, entry: TraceEntry) {
407	        if self.entries.len() < self.capacity {
408	            self.entries.push(entry);
409	        } else {
410	            self.entries[self.head] = entry;
411	        }
412	        self.head = (self.head + 1) % self.capacity;
413	        self.count += 1;
414	    }
415	
416	    /// Get the last N entries in chronological order
417	    pub fn last_n(&self, n: usize) -> Vec<&TraceEntry> {
418	        let len = self.entries.len();
419	        let n = n.min(len);
420	        let mut result = Vec::with_capacity(n);
421	        for i in 0..n {
422	            let idx = if len < self.capacity {
423	                // Not yet wrapped
424	                len - n + i
425	            } else {
426	                (self.head + self.capacity - n + i) % self.capacity
427	            };
428	            result.push(&self.entries[idx]);
429	        }
430	        result
431	    }
432	
433	    /// Get all entries in chronological order
434	    pub fn all(&self) -> Vec<&TraceEntry> {
435	        self.last_n(self.entries.len())
436	    }
437	
438	    /// Total number of entries ever recorded
439	    pub fn total_count(&self) -> usize {
440	        self.count
441	    }
442	
443	    /// Number of entries currently in buffer
444	    pub fn len(&self) -> usize {
445	        self.entries.len()
446	    }
447	
448	    /// Check if buffer is empty
449	    pub fn is_empty(&self) -> bool {
450	        self.entries.is_empty()
451	    }
452	
453	    /// Clear all entries
454	    pub fn clear(&mut self) {
455	        self.entries.clear();
456	        self.head = 0;
457	        self.count = 0;
458	    }
459	
460	    /// Format the last N entries as a multi-line string
461	    pub fn format_last(&self, n: usize) -> String {
462	        let entries = self.last_n(n);
463	        let mut out = String::new();
464	        out.push_str(&format!(
465	            "--- Trace (last {} of {} total) ---\n",
466	            entries.len(),
467	            self.count
468	        ));
469	        out.push_str(&format!(
470	            "{:>5} {:>8}  {:<24}  {}\n",
471	            "#", "PC", "Instruction", "Changes"
472	        ));
473	        for entry in &entries {
474	            out.push_str(&format!("{}\n", entry));
475	        }
476	        out
477	    }
478	}
