480	/// COR24 CPU state
481	#[derive(Clone, Serialize, Deserialize)]
482	pub struct CpuState {
483	    /// Program counter (24-bit)
484	    pub pc: u32,
485	    /// Register file (8 x 24-bit registers)
486	    pub registers: [u32; 8],
487	    /// Condition flag (NOT carry — set by ceq/cls/clu, tested by brt/brf)
488	    pub c: bool,
489	    /// SRAM (1 MB, 0x000000-0x0FFFFF)
490	    pub memory: Vec<u8>,
491	    /// Embedded Block RAM (8 KB, mapped at 0xFEE000-0xFEFFFF)
492	    pub ebr: Vec<u8>,
493	    /// Halted flag
494	    pub halted: bool,
495	    /// Interrupt-in-service flag (prevents nested interrupts)
496	    pub intis: bool,
497	    /// Cycle count
498	    pub cycles: u64,
499	    /// Instruction count
500	    pub instructions: u64,
501	    /// I/O peripheral state
502	    pub io: IoState,
503	    /// Instruction execution trace (ring buffer, not serialized)
504	    #[serde(skip)]
505	    pub trace: TraceBuffer,
506	}
507	
508	impl Default for CpuState {
509	    fn default() -> Self {
510	        Self::new()
511	    }
512	}
513	
514	impl CpuState {
515	    /// Create a new CPU state with default values
516	    pub fn new() -> Self {
517	        let mut state = Self {
518	            pc: RESET_ADDRESS,
519	            registers: [0; 8],
520	            c: false,
521	            memory: vec![0; SRAM_SIZE],
522	            ebr: vec![0; EBR_SIZE],
523	            halted: false,
524	            intis: false,
525	            cycles: 0,
526	            instructions: 0,
527	            io: IoState::new(),
528	            trace: TraceBuffer::default(),
529	        };
530	        // Initialize stack pointer
531	        state.registers[4] = INITIAL_SP;
532	        state
533	    }
534	
535	    /// Reset CPU to initial state (preserves memory)
536	    pub fn reset(&mut self) {
537	        self.pc = RESET_ADDRESS;
538	        self.registers = [0; 8];
539	        self.registers[4] = INITIAL_SP;
540	        self.c = false;
541	        self.halted = false;
542	        self.intis = false;
543	        self.cycles = 0;
544	        self.instructions = 0;
545	        self.io = IoState::new();
546	        self.trace.clear();
547	    }
548	
549	    /// Hard reset (clears memory too)
550	    pub fn hard_reset(&mut self) {
551	        self.reset();
552	        self.memory.fill(0);
553	        self.ebr.fill(0);
554	    }
555	
556	    /// Check if address is in I/O region (0xFF0000-0xFFFFFF)
557	    fn is_io_addr(addr: u32) -> bool {
558	        (addr & 0xFF0000) == 0xFF0000
559	    }
560	
561	    /// Check if address is in EBR region (0xFEE000-0xFEFFFF)
562	    fn is_ebr_addr(addr: u32) -> bool {
563	        addr >= EBR_BASE && addr < EBR_BASE + EBR_SIZE as u32
564	    }
565	
566	    /// Read a byte from memory or I/O
567	    pub fn read_byte(&self, addr: u32) -> u8 {
568	        let addr = addr & 0xFFFFFF; // Mask to 24 bits
569	
570	        if Self::is_io_addr(addr) {
571	            self.read_io(addr)
572	        } else if Self::is_ebr_addr(addr) {
573	            self.ebr[(addr - EBR_BASE) as usize]
574	        } else if (addr as usize) < SRAM_SIZE {
575	            self.memory[addr as usize]
576	        } else {
577	            0 // Unmapped region
578	        }
579	    }
580	
581	    /// Write a byte to memory or I/O
582	    pub fn write_byte(&mut self, addr: u32, value: u8) {
583	        let addr = addr & 0xFFFFFF; // Mask to 24 bits
584	
585	        if Self::is_io_addr(addr) {
586	            self.write_io(addr, value);
587	        } else if Self::is_ebr_addr(addr) {
588	            self.ebr[(addr - EBR_BASE) as usize] = value;
589	        } else if (addr as usize) < SRAM_SIZE {
590	            self.memory[addr as usize] = value;
591	        }
592	        // Writes to unmapped regions are silently ignored
593	    }
594	
595	    /// Read from I/O register
596	    fn read_io(&self, addr: u32) -> u8 {
597	        match addr {
598	            IO_LEDSWDAT => self.io.switches,
599	            IO_INTENABLE => self.io.int_enable,
600	            // Effective line state — the wired-AND of master drive
601	            // and slave pull-down. SCL is master-only in our model
602	            // (no clock stretching yet).
603	            IO_I2C_SCL => self.io.master_scl as u8,
604	            IO_I2C_SDA => (self.io.master_sda && !self.io.i2c.slave_sda_pull) as u8,
605	            // SPI master-line state. IO_SPI_DATA returns the last
606	            // byte the master wrote to MOSI (until Phase C.3 wires the
607	            // shift register, at which point it returns slave-driven
608	            // MISO). SCLK / SELN are master-only in our model.
609	            IO_SPI_DATA => self.io.master_mosi,
610	            IO_SPI_SCLK => self.io.master_sclk as u8,
611	            IO_SPI_SELN => self.io.master_seln as u8,
612	            IO_UARTDATA => self.io.uart_rx,
613	            IO_UARTSTAT => {
614	                let mut status = 0u8;
615	                if self.io.uart_rx_ready {
616	                    status |= 0x01; // Bit 0: RX data ready
617	                }
618	                // Bit 1: CTS active (always asserted in emulation)
619	                status |= 0x02;
620	                if self.io.uart_rx_overflow {
621	                    status |= 0x04; // Bit 2: RX overflow
622	                }
623	                if self.io.uart_tx_busy {
624	                    status |= 0x80; // Bit 7: TX busy
625	                }
626	                status
627	            }
628	            _ => 0, // Unknown I/O address
629	        }
630	    }
631	
632	    /// Read from I/O with side effects (auto-acknowledge)
633	    /// This is the version that should be called during execution.
634	    pub fn read_byte_exec(&mut self, addr: u32) -> u8 {
635	        let addr = addr & 0xFFFFFF;
636	        if addr == IO_UARTDATA {
637	            let data = self.io.uart_rx;
638	            self.io.uart_rx_ready = false; // Auto-acknowledge: reading data clears ready
639	            data
640	        } else {
641	            self.read_byte(addr)
642	        }
643	    }
644	
645	    /// Write to I/O register
646	    fn write_io(&mut self, addr: u32, value: u8) {
647	        match addr {
648	            IO_LEDSWDAT => {
649	                self.io.leds = value;
650	            }
651	            IO_INTENABLE => {
652	                self.io.int_enable = value;
653	            }
654	            // Master driver: low bit becomes the line's released/driven
655	            // state (1 = released high, 0 = driven low). After updating
656	            // the master bit, advance the bus state machine on the new
657	            // effective lines (master AND'ed with the slave pull-down).
658	            IO_I2C_SCL => {
659	                self.io.master_scl = (value & 1) != 0;
660	                let eff_sda = self.io.master_sda && !self.io.i2c.slave_sda_pull;
661	                self.io.i2c.step(self.io.master_scl, eff_sda, self.instructions);
662	            }
663	            IO_I2C_SDA => {
664	                self.io.master_sda = (value & 1) != 0;
665	                let eff_sda = self.io.master_sda && !self.io.i2c.slave_sda_pull;
666	                self.io.i2c.step(self.io.master_scl, eff_sda, self.instructions);
667	            }
668	            // SPI master-line drivers. After persisting the master's
669	            // line state, advance the shift-register state machine —
670	            // it samples MOSI bit 0 on SCLK rising edges while SELN
671	            // is low, and resets mid-byte on SELN rises.
672	            IO_SPI_DATA => {
673	                self.io.master_mosi = value;
674	                self.io.spi.step(
675	                    self.io.master_sclk,
676	                    (self.io.master_mosi & 1) != 0,
677	                    self.io.master_seln,
678	                    self.instructions,
679	                );
680	            }
681	            IO_SPI_SCLK => {
682	                self.io.master_sclk = (value & 1) != 0;
683	                self.io.spi.step(
684	                    self.io.master_sclk,
685	                    (self.io.master_mosi & 1) != 0,
686	                    self.io.master_seln,
687	                    self.instructions,
688	                );
689	            }
690	            IO_SPI_SELN => {
691	                self.io.master_seln = (value & 1) != 0;
692	                self.io.spi.step(
693	                    self.io.master_sclk,
694	                    (self.io.master_mosi & 1) != 0,
695	                    self.io.master_seln,
696	                    self.instructions,
697	                );
698	            }
699	            IO_UARTDATA => {
700	                if self.io.uart_tx_busy {
701	                    // Write while busy — character dropped (hardware would ignore)
702	                    self.io.uart_tx_dropped += 1;
703	                } else {
704	                    self.io.uart_tx = value;
705	                    if value != 0 {
706	                        self.io.uart_output.push(value as char);
707	                    }
708	                    self.io
709	                        .uart_log
710	                        .push(UartDirection::Output, value, self.instructions);
711	                    // TX busy for N cycles (simulates transmission time)
712	                    if self.io.uart_tx_busy_cycles > 0 {
713	                        self.io.uart_tx_busy = true;
714	                        self.io.uart_tx_countdown = self.io.uart_tx_busy_cycles;
715	                    }
716	                    // cycles=0 means instant ready (legacy/test mode)
717	                }
718	            }
719	            IO_UARTSTAT if value & 0x04 != 0 => {
720	                // Writing bit 2 of status clears the RX overflow flag.
721	                self.io.uart_rx_overflow = false;
722	            }
723	            _ => {} // Ignore unknown I/O address
724	        }
725	    }
726	
727	    /// Tick UART timers — call after each instruction execution
728	    pub fn uart_tick(&mut self) {
729	        if self.io.uart_never_ready {
730	            // TX stays busy forever — tests that programs poll before writing
731	            return;
732	        }
733	        if self.io.uart_tx_countdown > 0 {
734	            self.io.uart_tx_countdown -= 1;
735	            if self.io.uart_tx_countdown == 0 {
736	                self.io.uart_tx_busy = false;
737	            }
738	        }
739	    }
740	
741	    /// Send a character to UART RX (simulates external input)
742	    pub fn uart_send_rx(&mut self, ch: u8) {
743	        if self.io.uart_rx_ready {
744	            self.io.uart_rx_overflow = true; // Previous data not read
745	        }
746	        self.io.uart_rx = ch;
747	        self.io.uart_rx_ready = true;
748	        self.io
749	            .uart_log
750	            .push(UartDirection::Input, ch, self.instructions);
751	    }
752	
753	    /// Read a 24-bit word from memory (little-endian)
754	    pub fn read_word(&self, addr: u32) -> u32 {
755	        let b0 = self.read_byte(addr) as u32;
756	        let b1 = self.read_byte(addr.wrapping_add(1)) as u32;
757	        let b2 = self.read_byte(addr.wrapping_add(2)) as u32;
758	        b0 | (b1 << 8) | (b2 << 16)
759	    }
760	
761	    /// Write a 24-bit word to memory (little-endian)
762	    pub fn write_word(&mut self, addr: u32, value: u32) {
763	        self.write_byte(addr, (value & 0xFF) as u8);
764	        self.write_byte(addr.wrapping_add(1), ((value >> 8) & 0xFF) as u8);
765	        self.write_byte(addr.wrapping_add(2), ((value >> 16) & 0xFF) as u8);
766	    }
767	
768	    /// Get register value (masked to 24 bits)
769	    pub fn get_reg(&self, reg: u8) -> u32 {
770	        self.registers[(reg & 0x07) as usize] & 0xFFFFFF
771	    }
772	
773	    /// Set register value (masked to 24 bits)
774	    pub fn set_reg(&mut self, reg: u8, value: u32) {
775	        self.registers[(reg & 0x07) as usize] = value & 0xFFFFFF;
776	    }
777	
778	    /// Sign extend 8-bit to 24-bit
779	    pub fn sign_extend_8(value: u8) -> u32 {
780	        if value & 0x80 != 0 {
781	            0xFFFF00 | (value as u32)
782	        } else {
783	            value as u32
784	        }
785	    }
786	
787	    /// Check if an interrupt should fire
788	    /// Hardware: ireq = uart_rxrdy && ienab; irqis = ireq && !intis
789	    pub fn interrupt_pending(&self) -> bool {
790	        self.io.uart_rx_ready && (self.io.int_enable & 0x01 != 0) && !self.intis
791	    }
792	
793	    /// Mask to 24 bits
794	    pub fn mask_24(value: u32) -> u32 {
795	        value & 0xFFFFFF
796	    }
797	
798	    /// Load program into memory at given address
799	    pub fn load_program(&mut self, start_addr: u32, data: &[u8]) {
800	        for (i, &byte) in data.iter().enumerate() {
801	            self.write_byte(start_addr + i as u32, byte);
802	        }
803	    }
804	}
