1	//! Integration-test scaffold for SPI demos.
2	//!
3	//! Saga step 001 (this file) lands the fixture-loads check + a
4	//! crash-free smoke run with no SPI bus emulation. With no SPI MMIO
5	//! state yet, the guest spins in `spixchg` waiting for SCLK reads to
6	//! return what it just wrote — but it neither halts nor executes an
7	//! invalid instruction, which is what the smoke test asserts.
8	//!
9	//! Later steps add the SPI MMIO state, the shift-register bus model,
10	//! and the `SpiDevice` trait + TMP125 device — at which point a third
11	//! e2e test will assert deterministic UART output (`"DD.DD\n"`) for a
12	//! configured temperature.
13	
14	use cor24_emulator::{EmulatorCore, StopReason};
15	
16	const TMP125_LGO: &str = concat!(
17	    env!("CARGO_MANIFEST_DIR"),
18	    "/examples/spi/tmp125/tmp125.lgo"
19	);
20	
21	fn load_fixture() -> EmulatorCore {
22	    let content = std::fs::read_to_string(TMP125_LGO)
23	        .unwrap_or_else(|e| panic!("Cannot read {TMP125_LGO}: {e}"));
24	    let mut core = EmulatorCore::new();
25	    core.load_lgo(&content, None)
26	        .unwrap_or_else(|e| panic!("Failed to load tmp125.lgo: {e}"));
27	    core
28	}
29	
30	#[test]
31	fn tmp125_fixture_loads() {
32	    let content = std::fs::read_to_string(TMP125_LGO).unwrap();
