        let demo_decoded = sign_extend_10(((h as u16) << 2) | ((l as u16) >> 6));
        assert_eq!(demo_decoded, -100); // -25.0 * 4
    }

    #[test]
    fn temp_register_max_positive_12bit() {
        // 127.9375°C = 0x7FF in 12-bit. Register: 0x7FF0.
        let mut d = Tmp101Device::new(0x4A);
