    }

    #[test]
    fn echo_returns_seed_first_then_previous_mosi() {
        let mut bus = SpiBusState::new();
        attach_echo(&mut bus, 0xA5);
        bus.step(false, false, false, 0); // select → on_select returns 0xA5

        // Master clocks 0x11, slave drives 0xA5 (the seed).
